-- ============================================================
-- SEED EXT 5: Módulo 19 — Hedging Language (ex 179-250)
-- Novos tópicos: hedging em TOEFL essays avançados, boosters vs
-- hedges, hedging em diferentes tipos textuais, precisão epistêmica
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'hedging-language';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo hedging-language não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Boosters vs hedges — escolha e efeito
  (cid,51,179,'multiple_choice','What is the rhetorical difference between "The data suggests..." and "The data clearly demonstrates..."?','"Suggests" = hedge (uncertainty acknowledged). "Clearly demonstrates" = booster (certainty claimed).','["They are interchangeable","''Suggests'' = hedge (uncertainty acknowledged). ''Clearly demonstrates'' = booster (certainty claimed).","''Suggests'' = stronger. ''Clearly demonstrates'' = weaker.","Both are hedges but of different types."]','Hedges reduce epistemic commitment; boosters increase it. Academic writing prefers hedges for claims not fully established.','medium'),
  (cid,51,180,'gap_fill','The findings _____ (appear) to support the hypothesis, though the effect size _____ (remain) relatively modest and may not _____ (be) practically significant.','appear / remains / be',NULL,'"Appear + to support" = epistemic hedge. "Remain" = factual present. "May not be" = possibility hedge.','medium'),
  (cid,51,181,'gap_fill','It _____ (seem) likely that automation _____ (affect) employment across a wide range of sectors, though the precise magnitude and timing of displacement _____ (remain) uncertain.','seems / will affect / remains',NULL,'"It seems likely" = strong hedge + will = moderate certainty + "remains uncertain" = acknowledges limits.','medium'),
  (cid,51,182,'multiple_choice','Which of the following represents APPROPRIATE hedging for a claim about future trends?','The current trajectory suggests that urban populations may double in low-income countries by 2050.','["Urban populations will certainly double in low-income countries by 2050.","Urban populations may possibly probably double in low-income countries by 2050.","The current trajectory suggests that urban populations may double in low-income countries by 2050.","Urban populations might perhaps somewhat double in low-income countries by 2050."]','Single hedge "suggests" + "may" = appropriate epistemic caution without redundancy.','easy'),
  (cid,51,183,'gap_fill','While the hypothesis _____ (merit) further investigation, the available evidence _____ (not/sufficient) to _____ (draw) definitive conclusions about causality.','merits / is not sufficient / draw',NULL,'"Merits" (positive epistemic verb) + "is not sufficient" (negative factual) + infinitive.','medium'),

  -- BLOCK 52: Hedging com verbos epistêmicos
  (cid,52,184,'gap_fill','Researchers _____ (argue) that early childhood interventions _____ (be) the most cost-effective means of _____ (reduce) long-term inequality, _____ it _____ (acknowledge/passive) that the evidence _____ (not/uniformly/support) this view.','argue / are / reducing / though / is acknowledged / does not uniformly support',NULL,'Reporting verb "argue" (neutral) + multiple hedges + concessive acknowledgment.','hard'),
  (cid,52,185,'gap_fill','The mechanism by which X _____ (influence) Y _____ (not/fully/understand/passive), but _____ (hypothesize/passive) to involve a complex interaction of biological and environmental factors.','influences / is not fully understood / is hypothesized',NULL,'"Is hypothesized to involve" = epistemic verb passive + uncertainty acknowledgment.','hard'),
  (cid,52,186,'multiple_choice','Which reporting verb introduces a claim with the MOST CAUTION?','The authors speculate that increased cortisol levels may contribute to the observed decline in cognitive performance.','["The authors prove that increased cortisol levels cause the decline.","The authors speculate that increased cortisol levels may contribute to the observed decline in cognitive performance.","The authors confirm that increased cortisol levels cause the decline.","The authors demonstrate that increased cortisol levels contribute to the decline."]','"Speculate" = very tentative reporting verb. "Prove/confirm/demonstrate" = strong commitment.','medium'),
  (cid,52,187,'gap_fill','It _____ (propose/passive) that the divergence _____ (result) from structural differences in labor market institutions, though this interpretation _____ (challenge/passive) by scholars who _____ (emphasize) the role of macroeconomic demand.','has been proposed / results / has been challenged / emphasize',NULL,'Epistemic passive "has been proposed" + PS for proposed content + PP passive for challenge.','hard'),
  (cid,52,188,'gap_fill','There _____ (be) reason _____ (believe) that the relationship _____ (more/complex) than _____ (initially/suggest/passive), and _____ (warrant) further investigation.','is / to believe / is more complex / was initially suggested / this warrants',NULL,'"There is reason to believe" = hedge phrase + comparative claim + nominalization.','hard'),

  -- BLOCK 53: Hedging em diferentes seções acadêmicas
  (cid,53,189,'production','[TOEFL Writing — 100 words] Write a TOEFL essay introduction with appropriate hedging for a controversial claim about educational policy.','',NULL,'The relationship between school funding levels and educational outcomes is considerably more contested than public debate often suggests. While there is substantial evidence that adequately resourced schools perform better on average, the causal relationship appears to be mediated by a complex set of institutional and social variables that funding alone cannot address. This essay argues that increasing school funding is a necessary but not sufficient condition for improving educational outcomes for disadvantaged students, and that the design of how additional resources are used may matter as much as the total amount. Several lines of evidence will be examined to support this position.','hard'),
  (cid,53,190,'production','[TOEFL Writing — 100 words] Write a methods limitation paragraph with appropriate hedging.','',NULL,'Several methodological limitations should be acknowledged before interpreting these results. First, the study relied on self-reported data, which may be subject to social desirability bias, potentially leading to an overestimation of compliance with the intervention protocol. Second, while the sample was reasonably large, it was drawn from a single urban region and may not be representative of more rural or lower-income populations. Third, the follow-up period of six months may have been insufficient to capture longer-term behavioral change, which some studies in this domain suggest tends to emerge over 12 to 24 months. These limitations suggest that the findings should be interpreted with some caution and that replication in more diverse settings appears warranted.','hard'),
  (cid,53,191,'gap_fill','These results _____ (should/interpret/passive) cautiously, _____ the sample _____ (be) relatively small and the follow-up period _____ (may/not/be) sufficient _____ (detect) longer-term effects.','should be interpreted / as / was / may not have been / to detect',NULL,'Limitation hedging: should be interpreted + as + small sample + modal negative.','hard'),
  (cid,53,192,'gap_fill','The conclusions drawn from this analysis _____ (represent) the authors'' best assessment of the available evidence; _____, _____ (acknowledge/passive) that reasonable scholars _____ (disagree) about the interpretation of the data presented.','represent / nonetheless / it is acknowledged / may disagree',NULL,'"Represent best assessment" + "nonetheless, it is acknowledged" = transparent epistemic stance.','hard'),

  -- BLOCK 54: Distinguindo overclaiming e underclaiming
  (cid,54,193,'multiple_choice','Which sentence is OVERCLAIMING relative to the strength of the evidence?','This study proves that social media causes depression.','["This study provides evidence suggesting a possible association between social media use and depression.","This study found a statistically significant positive correlation between social media use and depression.","This study proves that social media causes depression.","This study''s findings are consistent with the hypothesis that social media may contribute to depression."]','"Proves that X causes" = overclaiming: one study cannot prove causation, and correlation ≠ causation.','easy'),
  (cid,54,194,'multiple_choice','Which sentence is UNDERCLAIMING (too hedged to be useful)?','This finding might possibly perhaps suggest a tentative indication that there could potentially be some possible relationship.','["This finding suggests a possible relationship between X and Y.","This finding may indicate a relationship between X and Y, though further research is needed.","This finding might possibly perhaps suggest a tentative indication that there could potentially be some possible relationship.","This finding provides evidence consistent with a relationship between X and Y."]','Stacked hedges ("might possibly perhaps suggest tentative indication could potentially") = underclaiming: so hedged it communicates nothing.','medium'),
  (cid,54,195,'gap_fill','The study found a _____ (statistical/significant) correlation (r = 0.43, p < .001) between X and Y; _____, correlation _____ (not/equal) causation, and experimental evidence _____ (need/passive) before causal claims _____ (make/passive).','statistically significant / however / does not equal / is needed / can be made',NULL,'Precision: statistical qualifier + "however" + correlation ≠ causation warning + modal passive.','hard'),
  (cid,54,196,'gap_fill','The results _____ (be) consistent with the theoretical framework proposed by X (2019), though _____ _____ (important) _____ (note) that the current study _____ (design/passive) _____ (test) the theory directly.','are / it is / important / to note / was not designed / to test',NULL,'"It is important to note" = hedging phrase + "was not designed to test" = limitation acknowledgment.','hard'),

  -- BLOCK 55: TOEFL Reading avançado — hedging
  (cid,55,197,'multiple_choice','[TOEFL Reading] "While X appears to improve outcomes, the evidence remains limited." The phrase "appears to" signals:','Epistemic uncertainty — the writer cannot fully confirm the improvement.','["Certainty","Epistemic uncertainty — the writer cannot fully confirm the improvement.","Past ability","A conditional"]','"Appears to" = hedge: the writer is not fully committed to the claim.','easy'),
  (cid,55,198,'gap_fill','[TOEFL Reading] "These findings _____ (suggest) that investment in early education _____ (have) significant long-term returns; _____, definitive conclusions _____ (premature)." Best hedged forms?','suggest / may have / however / would be premature / remain premature',NULL,'"Suggest" + "may have" + "however" + "would be/remain premature" = appropriately hedged academic claim.','medium'),
  (cid,55,199,'multiple_choice','[TOEFL Reading] "The proposed mechanism is thought to involve..." The phrase "is thought to" is used because:','The mechanism is not yet confirmed and represents current scientific thinking, not established fact.','["The mechanism is definitely confirmed","The mechanism is thought to = it is believed by someone unimportant","The mechanism is not yet confirmed and represents current scientific thinking, not established fact.","The mechanism is thought about but not acted on"]','"Is thought to" = epistemic passive hedge = current but tentative consensus.','medium'),
  (cid,55,200,'gap_fill','[TOEFL Reading] "The policy _____ (conceivably/result) in unintended consequences, particularly if implementation _____ (occur) before adequate safeguards _____ (put/passive) in place." Best hedged forms?','could conceivably result / occurs / are put',NULL,'"Could conceivably" = strong hedge + if + PS conditional + passive.','hard'),

  -- BLOCK 56: TOEFL Speaking avançado — hedging
  (cid,56,201,'production','[TOEFL Speaking — 45s] A reading suggests that remote work improves productivity. A lecture questions the evidence. Summarize using hedging language throughout.','',NULL,'The reading presents evidence suggesting that remote work may improve employee productivity, citing surveys in which a majority of workers reported higher output and greater satisfaction when working from home. However, the lecture raises several concerns about the reliability of this evidence. The professor argues that the evidence is primarily based on self-reported productivity measures, which may not accurately reflect actual output and could be subject to social desirability bias. Furthermore, the professor notes that the studies cited appear to have been conducted primarily during the early phase of the pandemic, when conditions were atypical; it is not clear that these findings would hold under normal circumstances. The lecture also suggests that the productivity effects of remote work are likely to vary considerably depending on the nature of the work involved, with collaborative and creative tasks seeming to benefit less from remote arrangements than individual, task-based work. The professor concludes that while remote work may offer benefits in specific contexts, the evidence does not appear sufficient to support broad claims about productivity improvement.','hard'),
  (cid,56,202,'production','[TOEFL Speaking — 45s] Discuss what the evidence suggests about the relationship between income inequality and health outcomes. Use hedging throughout.','',NULL,'The relationship between income inequality and population health appears to be one of the more robustly documented findings in social epidemiology, though the precise mechanisms through which inequality influences health outcomes remain somewhat contested. Research by Wilkinson and Pickett and others suggests that more unequal societies tend to have worse average health outcomes, even controlling for absolute income levels — a finding that seems to hold across a range of health indicators from life expectancy to mental illness prevalence. Several hypotheses have been advanced to explain this relationship: inequality may affect health by eroding social trust and cohesion, increasing chronic psychosocial stress, or reducing the effectiveness of collective public health investments. However, it should be noted that establishing a causal relationship is methodologically challenging, since inequality and health outcomes are both shaped by a large number of underlying factors that may account for the observed correlation. Some researchers argue that absolute income levels matter more than relative inequality for health outcomes, and this debate has not been fully resolved. The evidence seems to suggest that addressing inequality would likely improve average health outcomes, but the magnitude of such effects remains uncertain.','hard'),

  -- BLOCK 57: TOEFL Writing avançado
  (cid,57,203,'production','[TOEFL Writing — 200 words] Write a body paragraph on the effectiveness of international aid using hedging throughout.','',NULL,'The effectiveness of international development aid has been subject to extensive and often acrimonious debate, and the evidence, when examined carefully, appears to support a more nuanced conclusion than either enthusiastic proponents or sharp critics typically acknowledge. Some studies suggest that aid has contributed to improvements in specific outcome areas — childhood vaccination rates, primary school enrollment, and access to basic water and sanitation — in contexts where it has been channeled through effective government systems and civil society organizations with strong implementation capacity. However, the evidence for aid''s impact on broader economic growth seems considerably more mixed: early claims by researchers such as Sachs that substantial aid transfers could generate self-sustaining growth in low-income countries have not been strongly supported by subsequent empirical work, and there may even be circumstances in which aid has inadvertently weakened domestic institutions or created aid dependency that constrains long-term development. It appears likely that the effectiveness of aid depends heavily on recipient country governance conditions, the alignment of aid flows with country-owned development strategies, and the degree to which aid is fragmented across donors with competing priorities. The evidence seems to suggest that aid is a useful but limited tool that requires careful design and coordination to achieve meaningful, sustainable impact.','hard'),
  (cid,57,204,'production','[TOEFL Writing — 200 words] Write a paragraph on the long-term effects of colonialism using hedging and attribution throughout.','',NULL,'The long-term economic and institutional effects of colonial rule on formerly colonized societies remain a subject of active scholarly debate, with researchers offering competing hypotheses about both the direction and the magnitude of colonial legacies. Acemoglu, Johnson, and Robinson (2001) argue that settler mortality determined the type of institutions colonial powers established, which in turn appears to have had lasting consequences for post-independence development trajectories; countries where colonial powers established extractive institutions seem to have experienced systematically worse economic outcomes than those where settler colonies with more inclusive institutions were created. Other scholars argue that this analysis attributes too much explanatory power to colonial institutions relative to pre-colonial state capacity, geographic factors, and post-independence policy choices. It is widely acknowledged that colonialism involved the systematic extraction of resources, the distortion of local economies toward export commodity production, and the suppression of local institutional development — consequences that appear to have been economically harmful in most contexts. However, attributing specific contemporary inequalities solely to colonial legacies may be methodologically problematic, given the difficulty of constructing credible counterfactuals for what development might have looked like without colonization. What seems clearer is that post-colonial states inherited significantly compromised starting conditions, and that addressing these legacies likely required institutional investment that most receiving countries did not receive after independence.','hard'),

  -- BLOCK 58: Final
  (cid,58,205,'production','[TOEFL Writing — 200 words] Write a paragraph on mental health treatment effectiveness using hedging, attribution, and precision throughout.','',NULL,'The evidence on the effectiveness of different mental health treatments suggests that no single approach is universally superior, and that matching treatment to patient characteristics, preferences, and context appears to matter substantially. For moderate to severe depression, a combination of antidepressant medication and cognitive-behavioral therapy seems to produce better outcomes than either treatment alone, according to several well-designed randomized controlled trials; however, response rates remain highly variable, with estimates suggesting that approximately one-third of patients fail to achieve adequate symptom relief even with optimal first-line treatment. Psychotherapy has been shown to be effective for a range of conditions beyond depression, though the specific mechanisms of change and the relative efficacy of different therapeutic modalities remain areas of active research. There is growing evidence that social interventions — addressing social isolation, housing instability, and financial precarity — may be as important as clinical treatment for mental health outcomes in many populations, suggesting that a purely clinical model of mental health may be overly narrow. Digital mental health interventions have shown promise in some trials, though the quality of evidence is variable and it is not yet clear which patient populations benefit most or what the optimal format and intensity of digital interventions might be. It seems reasonable to conclude that mental health care requires genuinely personalized approaches that the current system is not yet reliably able to deliver.','hard'),
  (cid,58,206,'production','[TOEFL Writing — 200 words] Write a conclusion for a TOEFL essay on economic growth vs environmental sustainability using hedging throughout.','',NULL,'This essay has argued that the relationship between economic growth and environmental sustainability is considerably more complex than a simple trade-off framing suggests, though it appears clear that economic growth as currently measured and structured is not sustainable over the long run. The evidence examined suggests that decoupling economic activity from environmental damage is achievable in some dimensions — particularly energy efficiency and the carbon intensity of electricity generation — but that absolute decoupling of GDP growth from total material throughput has not been demonstrated at the scale or pace that sustainability would require. It seems likely that achieving both economic development and environmental sustainability will require a fundamental redesign of economic metrics, incentive structures, and governance frameworks, rather than merely incremental improvements within existing systems. Whether such redesign is politically achievable within democratic systems that face short electoral cycles and powerful incumbent interests in existing industrial structures is perhaps the most fundamental uncertainty. The analysis suggests that the choices made over the next decade will substantially determine which future is more probable — a managed transition toward a more sustainable economic model or an increasingly disruptive collision between ecological limits and economic growth imperatives. The evidence for which path leads where seems relatively clear; the political economy of choosing the better path appears considerably less so.','hard'),
  (cid,58,207,'production','[TOEFL Speaking — 60s] Discuss the evidence on whether economic sanctions are effective foreign policy tools. Use hedging throughout.','',NULL,'The evidence on the effectiveness of economic sanctions as a foreign policy tool appears to be more mixed and context-dependent than either enthusiastic proponents or determined critics typically acknowledge. On one hand, there are cases in which sanctions seem to have contributed to the policy changes they targeted: sanctions against South Africa are widely argued to have contributed to the end of apartheid, and the sanctions regime against Iran appears to have brought Iranian negotiators to the table for the nuclear agreement reached in 2015. However, establishing that sanctions caused these outcomes is methodologically challenging, since it is difficult to rule out the contribution of other concurrent pressures. The evidence from a broader analysis of historical cases suggests that comprehensive economic sanctions succeed in achieving their stated objectives in a minority of cases — estimates vary considerably but suggest success rates well below 50%. It appears that sanctions are most likely to be effective when they are multilateral rather than unilateral, when the targeted behavior is relatively modest in scale, and when the target country has trade relationships with sanctioning countries that make economic costs significant. Where the targeted behavior involves what the sanctioned government considers a core national security interest, sanctions seem considerably less likely to produce compliance. The evidence suggests that sanctions may be most useful as one element of a broader diplomatic strategy, rather than as a stand-alone coercive instrument.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
